import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState('');
  const [sourceLang, setSourceLang] = useState('ja');
  const [targetLang, setTargetLang] = useState('en');
  const [processedImage, setProcessedImage] = useState('');
  const [translatedTexts, setTranslatedTexts] = useState([]);
  const [statusLog, setStatusLog] = useState([]);
  const [boxImage, setBoxImage] = useState('');
  const [showBoxes, setShowBoxes] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const languageOptions = [
    { value: 'en', label: 'English' },
    { value: 'ja', label: 'Japanese' },
    { value: 'fr', label: 'French' },
    { value: 'zh', label: 'Chinese' },
    { value: 'ko', label: 'Korean' },
    { value: 'hi', label: 'Hindi' },
    { value: 'es', label: 'Spanish' },
    { value: 'de', label: 'German' },
    { value: 'ru', label: 'Russian' }
  ];

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
    setPreview(URL.createObjectURL(selectedFile));
    setStatusLog([]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file) {
      setError('Please select a file first');
      return;
    }

    setLoading(true);
    setError('');
    setProcessedImage('');
    setTranslatedTexts([]);
    setBoxImage('');
    setStatusLog([]);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('source_lang', sourceLang);
    formData.append('target_lang', targetLang);
    formData.append('show_boxes', showBoxes);

    try {
      const response = await axios.post('http://localhost:8000/process/', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      setProcessedImage(`http://localhost:8000${response.data.processed_image}`);
      setTranslatedTexts(response.data.translated_texts || []);
      setBoxImage(response.data.visualized_boxes_image ? `http://localhost:8000${response.data.visualized_boxes_image}` : '');
    } catch (err) {
      setError('Processing failed. Please check the file and try again.');
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="app-container">
      <h1 className="app-title">📘 Manga Panel Translator</h1>

      <form onSubmit={handleSubmit} className="upload-form">
        <div className="form-group">
          <label className="form-label">Upload File (.png, .jpg, .jpeg):</label>
          <input type="file" accept=".png,.jpg,.jpeg" onChange={handleFileChange} className="form-input" />
        </div>

        <div className="form-group">
          <label className="form-label">Source Language:</label>
          <select value={sourceLang} onChange={(e) => setSourceLang(e.target.value)} className="form-select">
            {languageOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Target Language:</label>
          <select value={targetLang} onChange={(e) => setTargetLang(e.target.value)} className="form-select">
            {languageOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </div>

        <div className="form-group checkbox-group">
          <label className="form-label">
            <input type="checkbox" checked={showBoxes} onChange={(e) => setShowBoxes(e.target.checked)} />
            Show Bounding Boxes
          </label>
        </div>

        <button type="submit" disabled={loading} className="submit-button">
          {loading ? 'Processing...' : 'Translate'}
        </button>

        {error && <div className="error-message">{error}</div>}
      </form>

      {preview && (
        <div className="preview-container">
          <h3>Original Preview:</h3>
          <img src={preview} alt="Preview" className="preview-image" />
        </div>
      )}

      {processedImage && (
        <div className="result-container">
          <h2>Processed Image:</h2>
          <img src={processedImage} alt="Processed" className="processed-image" />
          <div>
            <a href={processedImage} download className="download-button">Download Processed Image</a>
          </div>
        </div>
      )}

      {boxImage && (
        <div className="result-container">
          <h2>Bounding Box Overlay:</h2>
          <img src={boxImage} alt="Bounding Boxes" className="processed-image" />
          <div>
            <a href={boxImage} download className="download-button">Download Bounding Box Image</a>
          </div>
        </div>
      )}

      {translatedTexts.length > 0 && (
        <div className="translated-texts-container">
          <h3>Detected & Translated Texts:</h3>
          <ul className="translated-texts-list">
            {translatedTexts.map((item, idx) => (
              <li key={idx}>
                <strong>{item.text}</strong> (x: {item.position.x}, y: {item.position.y})
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

export default App;
